public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Starts recording of an active group call; for video chats only. Requires groupCall.can_be_managed right
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> StartGroupCallRecordingAsync(int groupCallId = default, string title = default, bool recordVideo = default, bool usePortraitOrientation = default)
    {

           using var activity =  StartCallActivity("StartGroupCallRecordingAsync", typeof(StartGroupCallRecording).FullName ?? "StartGroupCallRecordingAsync");

           try
           {
             return client.StartGroupCallRecordingAsync(groupCallId, title, recordVideo, usePortraitOrientation);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
